from pathlib import Path

p = Path(__file__).with_name('pulsar-design.html')
s = p.read_text(encoding='utf-8')
css = '''
/* 以本地 Linear 设计体系的暗色层次为主，保留星脉品牌色。 */
:root{--bg:#080f19;--ink:#eef2f5;--muted:#9caabd;--line:#bed4f51c;--gold:#cdb789}body{background:var(--bg)}header{background:#080f19ed}.draft{background:#060b12}.hero{background:radial-gradient(ellipse at 76% 45%,#2b598d38,transparent 53%);min-height:760px}.hero:before{content:"";position:absolute;inset:0;pointer-events:none;background-image:linear-gradient(#b6cbe909 1px,transparent 1px),linear-gradient(90deg,#b6cbe909 1px,transparent 1px);background-size:70px 70px;mask-image:linear-gradient(90deg,transparent,#000)}.hero h1{font-weight:500;letter-spacing:0;font-size:clamp(42px,5.2vw,74px);line-height:1.35}.hero h1 em{background:linear-gradient(100deg,#f1dfba,#aa8d5a);background-clip:text;color:transparent}.primary{border:1px solid #e7d5b455;border-radius:5px;box-shadow:inset 0 1px 0 #ffffff40,0 8px 30px #0003}.hero-foot{color:#8b9bb1}.intro{background:#101b2a;color:var(--ink);border-block:1px solid var(--line);position:relative}.intro p{color:#a7b5c7}.intro .eyebrow{color:var(--gold)}.intro h2{font-size:36px}.intro:after{content:"P / 01";position:absolute;right:6%;bottom:24px;font:10px monospace;letter-spacing:3px;color:#687b96}.lines{background:radial-gradient(ellipse at 50% 55%,#1a304331,transparent 70%)}.section-head h2{font-size:clamp(28px,3vw,40px);letter-spacing:0}.business-grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}.business{border:1px solid #bdd3f51c;border-radius:8px;background:linear-gradient(140deg,#17263880,#0c162380);overflow:hidden;transition:border-color .3s,box-shadow .3s;align-self:start}.business:hover,.business[open]{border-color:#cdb78960;box-shadow:0 12px 40px #0003}.business summary{padding:30px!important;grid-template-columns:28px 1fr 24px;gap:16px;position:relative}.business h3{font-size:23px}.business-tags{grid-column:2;font-size:12px}.business summary .arrow{grid-column:3;grid-row:1}.business small{text-transform:uppercase;font-size:9px;letter-spacing:1.5px}.business-body{padding:0 30px 30px 74px}.business-body ul{display:block;font-size:14px;line-height:2.2}.business-visual{grid-column:1/-1;height:125px;margin:16px 0 5px;position:relative;background:radial-gradient(ellipse,#24425d66,transparent 70%);display:grid;place-items:center;border-bottom:1px solid var(--line)}.business-visual svg{width:230px;height:110px;overflow:visible;stroke:var(--gold);fill:none;stroke-width:1}.business-visual .bright{stroke:#d4e6ff;opacity:.85}.business-visual .faint{opacity:.25}.business:hover .business-visual svg{filter:drop-shadow(0 0 9px #cdb78955)}.business-visual:after{content:attr(data-caption);position:absolute;right:0;bottom:12px;font:8px monospace;letter-spacing:1px;color:#778ca8}.ir{margin:30px 6% 70px;padding:50px 5%;border:1px solid #bdd3f526;border-radius:8px;background:radial-gradient(ellipse at right,#2b4a6e55,#111e2d);position:relative}.ir:before{content:"";height:60px;width:2px;background:var(--gold);position:absolute;left:-1px;top:50px}footer{border-top:1px solid var(--line);background:#060c14}.contact-open{position:fixed;bottom:24px;right:24px;z-index:10;background:#17283b;color:var(--ink);border:1px solid #cdb78970;padding:14px 20px;border-radius:5px;box-shadow:0 10px 30px #0005;font-size:12px}.contact-open:before{content:"↗";color:var(--gold);margin-right:15px}dialog{border-radius:10px;box-shadow:0 25px 100px #0008}dialog h2{margin:25px 0}dialog .contact-value{font:18px Arial;display:block;color:#e7d5b4;margin:20px 0;overflow-wrap:anywhere}.contact-caption{font-size:11px!important}
@media(max-width:800px){.business-grid{grid-template-columns:1fr}.hero{min-height:960px}.hero h1{font-size:40px}.business summary{padding:24px!important}.business-body{padding-left:68px}.intro h2{font-size:28px}.ir{margin:10px 6% 45px;padding:30px}.contact-open{bottom:15px;right:15px}.section-head p{margin-top:20px}}
'''
s = s.replace('</style>', css + '</style>')
start=s.index('<details class="business">')
end=s.index('</section>',start)
block=s[start:end]
visuals=[
    '<path class="faint" d="M10 85H220M10 55H220M10 25H220M40 10V100M95 10V100M150 10V100M205 10V100"/><path d="M15 85L65 67L100 75L140 40L175 50L220 16"/><circle class="bright" cx="140" cy="40" r="5"/><circle class="bright" cx="220" cy="16" r="4"/>',
    '<ellipse class="faint" cx="115" cy="55" rx="87" ry="35"/><ellipse cx="115" cy="55" rx="52" ry="35"/><path class="bright" d="M115 20V90M30 55H200"/><circle cx="115" cy="55" r="15"/><circle class="bright" cx="175" cy="31" r="5"/>',
    '<path class="faint" d="M25 55L80 20L150 20L205 55L150 90L80 90Z"/><path d="M25 55H205M80 20L150 90M150 20L80 90"/><circle class="bright" cx="115" cy="55" r="12"/><circle cx="25" cy="55" r="6"/><circle cx="205" cy="55" r="6"/>',
    '<path class="faint" d="M15 90H220M15 55H220M15 20H220"/><path d="M35 90V65H55V90M85 90V42H105V90M135 90V55H155V90M185 90V15H205V90"/><path class="bright" d="M35 50L85 25L135 35L200 5"/>'
]
for i,svg in enumerate(visuals):
    pos=block.index('<span class="business-tags">', block.index('<details',0) if i==0 else offset)
    insert='<div class="business-visual" data-caption="PULSAR / 0'+str(i+1)+'"><svg viewBox="0 0 230 110" aria-hidden="true">'+svg+'</svg></div>'
    # 技术图形放在摘要末尾，保持整个模块键盘可展开。
    closing=block.index('</summary>',pos)
    block=block[:closing]+insert+block[closing:]
    offset=closing+len(insert)+10
s=s[:start]+'<div class="business-grid">'+block+'</div>'+s[end:]
s=s.replace('</body>','''<button class="contact-open" type="button">联系星脉</button><dialog id="contact-card" aria-labelledby="contact-title"><button type="button" aria-label="关闭">×</button><small>CONNECT WITH PULSAR</small><h2 id="contact-title">连接下一次合作。</h2><p>业务合作 · 投资者沟通</p><span class="contact-value">ir@pulsar-dev.com</span><p class="contact-caption">邮箱来自初稿，待确认。电话、微信二维码及办公地址待提供；此设计稿不发送咨询。</p><p>香港 · 北京 · 深圳 · 东京</p></dialog><script>const contactCard=document.querySelector('#contact-card');document.querySelector('.contact-open').addEventListener('click',()=>contactCard.showModal());contactCard.querySelector('button').addEventListener('click',()=>contactCard.close());</script></body>''')
p.write_text(s,encoding='utf-8')
